create table session_v2 (id text primary key, project_id text, workspace_id text, parent_id text, fork_session_id text, fork_boundary text, slug text, directory text, path text, title text, version text, share_url text, summary_additions integer, summary_deletions integer, summary_files integer, summary_diffs text, metadata text, cost real, tokens_input integer, tokens_output integer, tokens_reasoning integer, tokens_cache_read integer, tokens_cache_write integer, revert text, permission text, agent text, model text, time_created integer, time_updated integer, time_compacting integer, time_archived integer, time_suspended integer, resume_attempts integer, time_idle integer, time_viewed integer, idle_outcome text);
create table session_message (id text primary key, session_id text, type text, seq integer, time_created integer, time_updated integer, data text);
